def add(index, entities, pairs, notes, *, entity_reason='', relation_reason='', groups=()):
    # Explicit literals/labels/pairs below are the semantic source, never keyword-generated.
    DECISIONS.append({'index': index, 'entityStatus': 'unresolved' if entity_reason else 'complete',
        'entityReason': entity_reason, 'entities': [{'text': text, 'label': label} for text, label in entities],
        'groupMentions': [{'text': text, 'label': M} for text in groups],
        'relationStatus': 'unresolved' if relation_reason else 'complete', 'relationReason': relation_reason,
        'relations': [{'head': f'e{head}', 'tail': f'e{tail}', 'label': label, 'reason': reason}
                      for head, tail, label, reason in pairs], 'notes': notes})


